from pathlib import Path

p = Path("src/components/TracksPlayer.jsx")
s = p.read_text()

# Remove the temporary test text from all previous versions.
s = s.replace('<div className="nyxtryp-auto-test">ПРИВЕТ</div>', '')
s = s.replace('ПРИВЕТ', '')

# Replace only the meter markup. The rest of TracksPlayer stays untouched.
start_marker = '''          {!isMobile && (\n            <div className="tracks-mc-vu">'''
start = s.find(start_marker)
if start < 0:
    raise SystemExit("L/R meter block start not found")
end_marker = '''          )}'''
end = s.find(end_marker, start)
if end < 0:
    raise SystemExit("L/R meter block end not found")
end += len(end_marker)

new_block = '''          {!isMobile && (\n            <div className="tracks-mc-vu">\n              {[['L', leftVU], ['R', rightVU]].map(([channel, value]) => {\n                const displayValue = Math.max(-40, Math.min(10, value))\n                const normalized = (displayValue + 40) / 50\n                const angle = -43 + normalized * 86\n\n                return (\n                  <div className="tracks-mc-meter" key={channel}>\n                    <div className="tracks-mc-window">\n                      <svg\n                        className="tracks-mc-gauge"\n                        viewBox="0 0 360 150"\n                        preserveAspectRatio="xMidYMid meet"\n                        aria-label={`${channel} dB meter`}\n                      >\n                        <defs>\n                          <linearGradient id={`mc-blue-${channel}`} x1="0" y1="0" x2="0" y2="1">\n                            <stop offset="0" stopColor="#6edcff" />\n                            <stop offset="0.42" stopColor="#22a9e8" />\n                            <stop offset="1" stopColor="#0875ad" />\n                          </linearGradient>\n                          <radialGradient id={`mc-light-${channel}`} cx="50%" cy="56%" r="72%">\n                            <stop offset="0" stopColor="#b9efff" stopOpacity=".28" />\n                            <stop offset=".62" stopColor="#56caff" stopOpacity=".08" />\n                            <stop offset="1" stopColor="#001522" stopOpacity="0" />\n                          </radialGradient>\n                          <filter id={`mc-glow-${channel}`} x="-30%" y="-30%" width="160%" height="160%">\n                            <feGaussianBlur stdDeviation="2" />\n                          </filter>\n                        </defs>\n\n                        <!-- Horizontal black-framed blue glass window -->\n                        <rect x="2" y="2" width="356" height="146" rx="3" fill="#05090c" stroke="#26333a" strokeWidth="2" />\n                        <rect x="7" y="7" width="346" height="136" rx="1" fill={`url(#mc-blue-${channel})`} />\n                        <rect x="7" y="7" width="346" height="136" rx="1" fill={`url(#mc-light-${channel})`} />\n                        <rect x="8" y="8" width="344" height="134" rx="1" fill="none" stroke="rgba(255,255,255,.13)" />\n\n                        <!-- MA9500-like shallow, wide meter arc -->\n                        <path d="M43 108 Q180 72 317 108" fill="none" stroke="rgba(2,39,63,.80)" strokeWidth="2.1" />\n                        <path d="M43 106 Q180 70 317 106" fill="none" stroke="rgba(213,246,255,.16)" strokeWidth=".8" />\n\n                        <!-- Ten small graduations + six labelled 10 dB positions -->\n                        {Array.from({ length: 11 }, (_, i) => {\n                          const db = -40 + i * 5\n                          const t = i / 10\n                          const x = 43 + 274 * t\n                          const y = 108 - 36 * (4 * t * (1 - t))\n                          const slope = 144 * (t - 0.5)\n                          const length = i % 2 === 0 ? 8 : 4.5\n                          const norm = Math.hypot(1, slope)\n                          const nx = -slope / norm\n                          const ny = -1 / norm\n                          const major = i % 2 === 0\n                          return (\n                            <g key={db}>\n                              <line\n                                x1={x - nx * 1}\n                                y1={y - ny * 1}\n                                x2={x + nx * length}\n                                y2={y + ny * length}\n                                stroke="rgba(3,35,57,.92)"\n                                strokeWidth={major ? 1.5 : 1}\n                              />\n                              {major && (\n                                <text\n                                  x={x + nx * 15}\n                                  y={y + ny * 15 + 3}\n                                  textAnchor="middle"\n                                  fill="rgba(3,34,55,.95)"\n                                  fontSize="8.5"\n                                  fontFamily="Arial, sans-serif"\n                                >\n                                  {db > 0 ? `+${db}` : db}\n                                </text>\n                              )}\n                            </g>\n                          )\n                        })}\n\n                        <text x="180" y="22" textAnchor="middle" fill="rgba(3,35,56,.96)" fontSize="8" fontWeight="700" fontFamily="Arial, sans-serif" letterSpacing="2">dB</text>\n                        <text x="180" y="137" textAnchor="middle" fill="rgba(3,32,51,.94)" fontSize="7.5" fontWeight="700" fontFamily="Arial, sans-serif" letterSpacing="1.7">POWER OUTPUT</text>\n\n                        <!-- Fine analog needle and pivot -->\n                        <line x1="180" y1="112" x2="180" y2="44" stroke="rgba(220,249,255,.22)" strokeWidth="4" strokeLinecap="round" filter={`url(#mc-glow-${channel})`} />\n                        <g transform={`rotate(${angle} 180 112)`}>\n                          <line x1="180" y1="112" x2="180" y2="43" stroke="#f3fbff" strokeWidth="1.9" strokeLinecap="round" />\n                          <line x1="180" y1="112" x2="180" y2="49" stroke="rgba(22,64,88,.90)" strokeWidth=".8" strokeLinecap="round" />\n                        </g>\n                        <circle cx="180" cy="112" r="4.6" fill="#d9e9f0" stroke="#17394e" strokeWidth="1.5" />\n                        <circle cx="180" cy="112" r="1.45" fill="#07131b" />\n                      </svg>\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          )}'''

s = s[:start] + new_block + s[end:]

# Replace the old meter CSS only.
css_start_marker = '''        .tracks-mc-vu {'''
css_start = s.find(css_start_marker)
if css_start < 0:
    raise SystemExit("meter CSS start not found")
css_end_marker = '''        @media (max-width: 600px) {'''
css_end = s.find(css_end_marker, css_start)
if css_end < 0:
    raise SystemExit("meter CSS end not found")

new_css = '''        .tracks-mc-vu {\n          display: flex;\n          gap: 14px;\n          width: 100%;\n          justify-content: center;\n          align-items: stretch;\n          padding: 1px 0 3px;\n        }\n\n        .tracks-mc-meter {\n          flex: 1 1 0;\n          min-width: 0;\n        }\n\n        .tracks-mc-window {\n          position: relative;\n          overflow: hidden;\n          border-radius: 3px;\n          background: #05090c;\n          border: 1px solid rgba(190,214,228,.42);\n          box-shadow: inset 0 0 0 1px rgba(0,0,0,.95), 0 4px 14px rgba(0,0,0,.28);\n        }\n\n        .tracks-mc-gauge {\n          position: relative;\n          z-index: 1;\n          width: 100%;\n          height: auto;\n          aspect-ratio: 360 / 150;\n          display: block;\n        }\n\n'''
s = s[:css_start] + new_css + s[css_end:]

p.write_text(s)
print("NYXTRYP: refined horizontal MA9500-inspired L/R meter structure; dB -40 to +10")